mapper.select:
SELECT id, sku_id AS skuId, sku_no AS skuNo, warehouse_id AS warehouseId, warehouse_area_code AS warehouseAreaCode, suggest_warehouse_location_code AS suggestWarehouseLocationCode, sort, disabled, version, is_deleted AS isDeleted, create_user_id AS createUserId, create_user_name AS createUserName, create_time AS createTime, update_user_id AS updateUserId, update_user_name AS updateUserName, update_time AS updateTime FROM aftersales_warehouse_location_suggest WHERE is_deleted = false
AND sku_no LIKE CONCAT('%', #{params.skuNo}, '%')
AND warehouse_id = #{params.warehouseId}
AND ${params.sqlMap.default}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
,
create_time DESC
